import 'package:flutter/material.dart';import 'package:introduction_screen/introduction_screen.dart';import '../../Config/Assets/image_png.dart';import '../../Features/Boarding/presentation/widgets/build_page_view_model.dart';import '../Utils/Extensions/localizations_extension.dart';class AppList {  static List<PageViewModel> buildPagesIntroductionScreen(      BuildContext context) {    return [      buildPageViewModel(        title: context.local.boarding1_title,        body: context.local.boarding1_body,        image: AppImagesPng.boarding1,      ),      buildPageViewModel(        title: context.local.boarding2_title,        body: context.local.boarding2_body,        image: AppImagesPng.boarding2,      ),      buildPageViewModel(        title: context.local.boarding3_title,        body: context.local.boarding3_body,        image: AppImagesPng.boarding3,      ),    ];  }}